import backtrader as bt


class FiftyTwoWeekHighTrailingStop(bt.Strategy):
    def __init__(self):
        self.high52 = bt.indicators.Highest(self.data.close, period=252)
        self.crossover = bt.indicators.CrossOver(self.data.close, self.high52(-1))
        self.order = None
        self.stop_order = None

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return
        if order is self.order:
            self.order = None
        if order is self.stop_order and order.status in [order.Completed, order.Rejected, order.Margin]:
            self.stop_order = None

    def next(self):
        if self.position:
            stop_price = self.high52[0] * 0.95
            limit_price = self.high52[0] * 0.90
            if self.stop_order is not None:
                self.cancel(self.stop_order)
            self.stop_order = self.sell(
                exectype=bt.Order.StopLimit,
                price=stop_price,
                plimit=limit_price,
                size=self.position.size,
            )
        elif not self.order:
            if self.crossover[0] > 0:
                cash = self.broker.getcash()
                price = self.data.close[0]
                size = int(cash / price)
                if size > 0:
                    self.order = self.buy(size=size)
